import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { userLogic } from 'scenes/userLogic'

import { UserType } from '~/types'

// pinned: localStorage key, renaming it reopens the explainer for everyone who closed it
const EXPLAINER_OPEN_STORAGE_KEY = 'data_catalog_explainer_open'

// pinned: key in the user's server-side `has_seen_product_intro_for`, renaming it brings the explainer
// back for everyone who dismissed it
export const EXPLAINER_DISMISSED_KEY = 'data_catalog_explainer'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogExplainerLogicValues {
    user: UserType | null // userLogic
    dismissedLocally: boolean
    explainerDismissed: boolean
    explainerOpen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogExplainerLogicActions {
    updateHasSeenProductIntroFor: (
        productKey: string,
        value?: boolean | undefined
    ) => {
        productKey: string
        value: boolean
    } // userLogic
    dismissExplainer: () => {
        value: true
    }
    setExplainerOpen: (open: boolean) => {
        open: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface catalogExplainerLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        explainerDismissed: (dismissedLocally: boolean, user: UserType | null) => boolean
    }
}

export type catalogExplainerLogicType = MakeLogicType<
    catalogExplainerLogicValues,
    catalogExplainerLogicActions,
    Record<string, any>,
    catalogExplainerLogicMeta
>

export const catalogExplainerLogic = kea<catalogExplainerLogicType>([
    path(['products', 'data_catalog', 'frontend', 'catalogExplainerLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
        actions: [userLogic, ['updateHasSeenProductIntroFor']],
    })),
    actions({
        setExplainerOpen: (open: boolean) => ({ open }),
        dismissExplainer: true,
    }),
    reducers({
        explainerOpen: [
            true,
            { persist: true, storageKey: EXPLAINER_OPEN_STORAGE_KEY },
            {
                setExplainerOpen: (_, { open }) => open,
            },
        ],
        // Hides the explainer at once; the user record confirms the dismissal after it reloads.
        dismissedLocally: [
            false,
            {
                dismissExplainer: () => true,
            },
        ],
    }),
    selectors({
        explainerDismissed: [
            (s) => [s.dismissedLocally, s.user],
            (dismissedLocally: boolean, user: UserType | null): boolean =>
                dismissedLocally || !!user?.has_seen_product_intro_for?.[EXPLAINER_DISMISSED_KEY],
        ],
    }),
    listeners(({ actions }) => ({
        setExplainerOpen: ({ open }) => {
            posthog.capture('data catalog explainer toggled', { open })
        },
        dismissExplainer: () => {
            actions.updateHasSeenProductIntroFor(EXPLAINER_DISMISSED_KEY)
            posthog.capture('data catalog explainer dismissed')
        },
    })),
])
